-- ========================================================
-- E-Commerce PostgreSQL Database Seeds
-- 20 Categories, 240 Products with Real Images, Deliveries & Transactions
-- ========================================================

-- 1. Categories
SELECT setval('categories_id_seq', (SELECT MAX(id) FROM categories));

-- 2. Products (240 items with real images)
SELECT setval('products_id_seq', (SELECT MAX(id) FROM products));

-- 3. Customers
SELECT setval('customers_id_seq', (SELECT MAX(id) FROM customers));

-- 4. Orders
SELECT setval('orders_id_seq', (SELECT MAX(id) FROM orders));

-- 5. Order Items
SELECT setval('order_items_id_seq', (SELECT MAX(id) FROM order_items));

-- 6. Product Deliveries
SELECT setval('product_deliveries_id_seq', (SELECT MAX(id) FROM product_deliveries));

-- 7. Delivery Timeline Checkpoints
SELECT setval('delivery_timeline_id_seq', (SELECT MAX(id) FROM delivery_timeline));

-- 8. Product Transactions History
SELECT setval('transactions_id_seq', (SELECT MAX(id) FROM transactions));

